INSERT INTO `marketing_requests` VALUES (1,79,'RH','RH','Outros','Arte de promoção','Já existe um modelo pronto','','[]','2026-01-12','Ester','','Concluído','2026-01-09 17:13:50'),(2,2,'Maria Júlia Azevedo','Diretoria Geral','Eventos','Cartilha de convite para inauguração dos serviços de audiologia ','Convite: Preparamos este presente para apresentar nossos novos serviços de audiologia, pensados para apoiar sua prática clínica e oferecer mais precisão no cuidado aos seus pacientes. Conte conosco como parceiros.”\r\n\r\nQuem somos/ Especialidades/ Convênios + Qr de confirmação','','[]','2026-01-13','IVANIZE','','Concluído','2026-01-09 19:47:00'),(3,2,'Maria Júlia Azevedo','Diretoria Geral','Modelo de Slide','Para fins de apresentação em reunião ','Reunião Diretoria Geral ','','[]','2026-01-13','IVANIZE','','Concluído','2026-01-12 19:33:52'),(4,2,'Maria Júlia Azevedo','Diretoria Geral','Eventos','Uma decoração para brinde ','A logo em cima , cha de camomila e o arroba','','[\"1768391866340-WhatsApp_Image_2026_01_14_at_08.55.49.jpeg\"]','2026-01-14','IVANIZE','','Concluído','2026-01-14 11:57:46'),(5,2,'Maria Júlia Azevedo','Diretoria Geral','Comunicado','Um card para ser enviado para os pais dos pacientes, a qual informará novos serviços auditivos','Prezadas famílias,\r\n\r\nÉ com grande satisfação que informamos que a Psiconeuro ampliará seus atendimentos, passando a oferecer serviços especializados em saúde auditiva, com laboratório próprio e estrutura adequada para avaliações e terapias.\r\n\r\nA partir do dia 19/01/2026, estarão disponíveis os seguintes serviços:\r\n\r\nAudiometria clínica\r\n\r\nImitanciometria\r\n\r\nAvaliação do Processamento Auditivo Central (PAC)\r\n\r\nTerapia em cabine acústica\r\n\r\nEsses novos serviços têm como objetivo proporcionar avaliações mais completas, diagnósticos precisos e intervenções eficazes, contribuindo para o desenvolvimento, aprendizagem e qualidade de vida de nossos pacientes.\r\n\r\nPara mais informações, agendamentos ou esclarecimento de dúvidas, nossa equipe está à disposição pelos canais habituais de atendimento.\r\n\r\nAtenciosamente,\r\nEquipe Psiconeuro','','[]','2026-01-15','IVANIZE','','Concluído','2026-01-15 11:36:31'),(6,79,'RH','RH','Post Instagram','Postagem de vagas ','Vaga para assistente Administrativo, carga horária 44 horas semanais.','','[\"1768505762787-card_administrativo__5_.png\"]','2026-01-16','Alexia ','Segue sugestão de Card','Concluído','2026-01-15 19:36:02'),(7,79,'RH','RH','Post Instagram','Card divulgação de vaga de emprego.','Vaga jovem aprendiz. Atividades administrativas','','[\"1768505867597-Jovem_Aprendiz.png\"]','2026-01-16','Alexia ','Segue card de sugestão','Concluído','2026-01-15 19:37:47'),(8,26,'Aurélia','Diretoria Pedagógica','Comunicado','Convite ','Querida equipe! 🌟\r\n\r\nÉ com muita alegria que convidamos todos para a inauguração da Sala de Audiologia, que acontecerá na segunda-feira (19/01), às 11h30.\r\n\r\nSerá um momento especial para celebrarmos juntos essa grande conquista.\r\nEsperamos vocês!','','[]','0000-00-00','Aurélia ','','Concluído','2026-01-16 11:23:12'),(9,17,'Taiane Espíndola','Agendamento','Comunicado','Comunicado padrão ','Comunicado\r\nInformamos que a profissional Crislene estará de férias no período de 19/01 a 02/02. Durante esse período, os atendimentos serão remanejados para outro profissional.\r\nAgradecemos a compreensão.','','[]','2025-01-16','Marcella ','Pode ser enviado até fim do dia.','Concluído','2026-01-16 18:55:08'),(10,79,'RH','RH','Eventos','Convite para palestra em alusão ao janeiro branco.\r\nData 27/01/2026 horário 16:00 local : sala de reuniões\r\nPalestrante :  Psicóloga Isadora Brasil','Janeiro Branco é um convite à reflexão sobre aquilo que mais importa: nossa saúde emocional.\r\n\r\nPensando nisso, convidamos você para a palestra, um espaço de conversa, escuta e conscientização sobre saúde mental, bem-estar e autocuidado no dia a dia.\r\n\r\n','','[]','2026-01-22','Alexia ','','Concluído','2026-01-19 17:54:32'),(11,79,'RH','RH','Outros','Cartaz para mural','Confecção do cartaz ','','[\"1768846004057-Arte_inspita____o_janeiro_branco.jpeg\"]','2026-01-22','Alexia ','','Concluído','2026-01-19 18:06:44'),(12,79,'RH','RH','Modelo de Slide','Arte da reunião que acontecerá no dia 26/01/2026 ás 10:40h na recepção da unidade Ipara apresentação dos projetos de rh para o ano de 2026.\r\nObs: preciso de modelo slide e card para post no grupo do whatsapp','CAFÉ COM RH \r\nHORARIO\r\nDATA\r\nLOCAL','','[]','2026-01-21','ALEXIA','','Concluído','2026-01-19 18:32:17'),(13,52,'Nathali','Coordenação TCC/AVN','Outros','Folder com a foto da profissional Marcella, psicoterapeuta','A profissional Marcella já está em atendimento na Clínica Psiconeuro para dar continuidade ao acompanhamento psicoterapêutico. Aguardamos você!','','[]','2026-01-22','Nathali','','Concluído','2026-01-22 18:49:56'),(14,52,'Nathali','Coordenação TCC/AVN','Outros','Post informativo','Prezados pais,\r\nInformamos que, a Psicóloga Crislenne passará também a assumir a condução de terapias em grupo. Com isto, alguns pacientes com faixa etária entre 3 e 6 anos serão destinados para acompanhamento com outra terapeuta da mesma área. \r\nRessaltamos que essa reorganização foi planejada com todo o cuidado, garantindo a continuidade do acompanhamento com o mesmo comprometimento, ética e atenção às necessidades de cada paciente.\r\n\r\nColocamo-nos à disposição para quaisquer esclarecimentos e agradecemos, desde já, a compreensão.','','[]','2026-01-23','Nathali','','Concluído','2026-01-23 14:27:20'),(15,1,'Marcus TI','Diretoria Geral','Post Instagram','Quero que faça mágica na minha foto institucional. Para me deixar como galã da novela das 8h. ','Não precisa de texto.','','[\"1769427147147-1765374924668_C__pia_de_fotos_2__1_.png\"]','2026-01-27','Maria Julia','','Negado','2026-01-26 11:32:27'),(16,79,'RH','RH','Outros','um cartão com um espaço para colar uma balinha personalizada ao lado','10 Dicas para cuidar da sua saúde mental:\r\n\r\nFale sobre seus sentimentos\r\n\r\nRespeite seus limites\r\n\r\nMantenha uma rotina equilibrada\r\n\r\nPriorize o sono\r\n\r\nPratique atividade física\r\n\r\nSeja mais gentil consigo mesmo\r\n\r\nFaça pausas e desacelere\r\n\r\nCuide da alimentação\r\n\r\nBusque ajuda profissional\r\n\r\nLembre-se de que você não está sozinho(a) 💙','seguindo o layout do convite da palestra de janeiro branco','[\"1769448364863-Captura_de_tela_2026_01_26_142217.png\"]','2026-01-26','Ester','','Concluído','2026-01-26 17:26:04'),(17,72,'VITÓRIA REGINA','Coordenação ABA','Modelo de Slide','Olá gostaria de solicitar a confeccção de um slide para reunião com equipe. ','Se possivel gostaria de marcar um horário para confecionar junto podendo ser hoje a tarde ou outro dia','','[]','2026-01-28','Vitória ','','Negado','2026-01-28 12:13:05'),(18,79,'RH','RH','Post Instagram','Já possuimos o card pronto','divulgação de vagas','','[\"1769691088543-story_instagram_oportunidade_de_emprego_moderno_verde__5_.png\",\"1769691088644-story_instagram_oportunidade_de_emprego_moderno_verde__4_.png\",\"1769691088733-story_instagram_oportunidade_de_emprego_moderno_verde__3_.png\"]','2026-02-02','Ester','','Concluído','2026-01-29 12:51:28'),(19,79,'RH','RH','Outros','Carteirinha de benefício Psiconeuro','Primeiro e último nome do colaborador e foto. Seguir modelo de crachá.','https://www.canva.com/design/DAGzFITuz1I/TIpmTXhFzYQ90j9qjZYSRw/edit','[]','2026-02-10','Ester','Caso precise de algo o RH está a disposição.','Concluído','2026-01-29 13:15:38'),(20,79,'RH','RH','Comunicado','VIDEO 1 borburinho\r\nVIDEO 2 importância fit dance - Neuziane e Ester\r\nVIDEO 3 Convite\r\nVIDEO 4 Professor\r\nVIDEO 5 Reforço convite ','VIDEO 1 borburinho\r\nVIDEO 2 importância fit dance - Neuziane e Ester\r\nVIDEO 3 Convite\r\nVIDEO 4 Professor\r\nVIDEO 5 Reforço convite ','','[]','2026-02-02','Alexia','','Concluído','2026-01-29 13:41:14'),(21,79,'RH','RH','Comunicado','Agendamento de apresentação do regulamento interno\r\n02/02/2026 ás 10:50h','Convocação de toda a equipe para aprsentação do regulamento interno da clinica Psiconeuro, na recepção da unidade I ás 10:50h','','[]','2026-01-30','ALEXIA','','Concluído','2026-01-29 18:39:10'),(22,3,'Tawany Sayure','Financeiro','Outros','corrigir um modelo de envelope para confeccionar ','encaminhado via neurochat','','[\"1769718142342-WhatsApp_Image_2026_01_29_at_17.18.37.jpeg\",\"1769718142529-F_pasta_c__orelha.pdf\"]','2026-02-02','Silvana','','Negado','2026-01-29 20:22:22'),(23,26,'Aurélia','Diretoria Pedagógica','Comunicado','Comunicado ','Senhores pais e responsáveis,\r\n\r\nNos dias 12 e 13 de fevereiro realizaremos o Bloquinho Psiconeuro, com atividades voltadas ao desenvolvimento de habilidades sociais, interação e socialização.\r\n\r\nAs atividades acontecerão no horário habitual das terapias. Caso a criança não possa participar por algum motivo, pedimos que nos avise para que possamos manter o atendimento normal.\r\n\r\nAgradecemos a parceria.                                                                                                                                                                     Diretoria Pedagógica ','','[]','2026-02-06','Aurélia ','','Concluído','2026-02-06 12:33:02'),(24,26,'Aurélia','Diretoria Pedagógica','Comunicado','Comunicado ','Assunto\r\n\r\nSenhores pais e responsáveis,\r\n\r\nPensando em proporcionar alguns dias de descanso à nossa equipe de terapeutas, sem comprometer os atendimentos, organizamos a semana do Carnaval da seguinte forma:\r\n\r\nOs atendimentos do dia 16 de fevereiro serão realizados no dia 12 de fevereiro, e os atendimentos do dia 17 de fevereiro acontecerão no dia 13 de fevereiro, mantendo-se os mesmos horários. Nessa ocasião, serão trabalhadas as habilidades sociais, a interação e a socialização.\r\n\r\nCaso a criança não possa participar por algum motivo, solicitamos, por gentileza, que nos avise para que possamos manter o atendimento normal.\r\n\r\nAtenciosamente,\r\nDiretoria Pedagógica','','[]','2026-02-06','Aurélia ','','Concluído','2026-02-06 18:56:13'),(25,79,'RH','RH','Outros','Card de aumento salarial, Um texto que encaixe a palavra Talento na frase, pois iremos ultilizar o chocolate talendo no card!','\r\nSeu talento impulsiona resultados, inspira o time e merece ser valorizado. É necessário a foto do colaborador. Precisamos de um espaço onde vamos específicar os valores. Ex: A partir da próxima folha sua remuneração será: Salário: Caju: Mobilidade: VR: ','','[]','2026-02-10','Ester','','Concluído','2026-02-10 12:28:58'),(26,79,'RH','RH','Comunicado','card de aviso sobre atestado e declaração ','Informamos que declarações médicas ou odontológicas de até 3 (três) horas serão abonadas.\r\nRessaltamos ainda que atestados médicos não necessitarão de homologação.\r\n\r\nA medida tem como objetivo visar uma melhor organização institucional.\r\n\r\nCaso haja necessidade, o setor responsável permanece à disposição para esclarecimentos.','','[]','2026-02-11','Ester','','Concluído','2026-02-10 12:33:02'),(27,79,'RH','RH','Outros','Queremos fazer uma homenagem para o dia da ASG. Queremos que os profissionais escrevam um recado para cada colocaborador de ASG, queremos uma folhinha personalizada onde os profissionais irão escrever a homenagem. A ideia é fazer uma cartinha personalizada para cada asg. Uma carta para o Nonato, uma para Josy, uma para a Raimunda, uma para a Rosenilda e outra para a Keliane. ','É interessante que tenha a identidade visual da clínica no papel.','','[\"1770809488408-Papel.jpg\"]','2026-02-13','Ester','','Concluído','2026-02-11 11:31:28'),(28,79,'RH','RH','Vídeo','Gravar a homenagem do dia da ASG que irá acontecer no dia 20/02/2026 às 15h na copa. Iremos servir um lanche da tarde para as coloaboradores.','Não tem ','','[]','2026-02-20','Ester','','Concluído','2026-02-11 11:33:01'),(29,79,'RH','RH','Outros','um crachá para a Dra Ivanize','Precisamos de ideia para layout','','[\"1770830769804-WhatsApp_Image_2026_02_11_at_13.45.06.jpeg\"]','2026-02-12','Ester','','Concluído','2026-02-11 17:26:09'),(30,73,'Larissa Guimarães','Diretoria Pedagógica','Comunicado','Imagem informativa para ser enviada aos pais em relação à semana de devolutivas.\r\nObs.: *Preciso que na imagem conste a mensagem de que os pacientes das profissionais Marina (TO) e Ana Carolina (ex- colaboradora de Fono), os atendimentos continuam normalmente com os pacientes.* ','A nossa semana de devolutivas está se aproximando e irá acontecer entre os dias 23/02 à 27/02. É importante que os pais/responsáveis compareceram para alinharem as demandas e acompanharem os ganhos/evoluções que seus filhos obtiveram. \r\n\r\nObs. Pode adaptar a linguagem. ','','[]','2026-02-20','Larissa','','Concluído','2026-02-18 14:36:36'),(31,79,'RH','RH','Outros','Um cartão para reconhecer e parabenizar a colaboradora Julyane e Vitória que se formaram. Iremos entregar junto com um chocolate. ','Enfim Psicóloga\r\n\r\nParabéns por essa grande conquista🎓\r\nEste é um momento único, que representa não apenas o fim de uma etapa, mas o começo de uma caminhada cheia de significado e realizações. Que você siga exercendo sua profissão com sensibilidade, ética e paixão.\r\n\r\nA Psiconeuro celebra com você e deseja muito sucesso nessa nova fase! 💙','','[]','2026-02-19','Ester','','Concluído','2026-02-18 14:48:30'),(32,95,'Alexia Santos','Diretora de RH e Estratégia','Comunicado','Alteração na arte de comunicado de promoção','texto que será publicado: 📢 Comunicado Interno – Promoção\r\n\r\nÉ com grande orgulho que comunicamos a promoção de [Nome do Colaborador(a)] para o cargo de [Novo Cargo], com início em [data de início].\r\n\r\nEssa conquista é resultado de uma trajetória construída com dedicação, responsabilidade, evolução constante e entregas que impactam diretamente nossos resultados. Sua postura profissional e comprometimento demonstram preparo para assumir desafios ainda maiores.\r\n\r\nA partir desta nova etapa, [Nome] passa a ser responsável por [principais responsabilidades], fortalecendo ainda mais nossa estrutura e contribuindo estrategicamente para o crescimento sustentável da empresa.\r\n\r\nSeguimos firmes no nosso propósito de atender, satisfazer e encantar, e temos plena confiança de que, nessa nova função, você continuará sendo exemplo desse compromisso no dia a dia.\r\n\r\nParabéns por essa conquista! 🚀\r\nQue essa nova fase seja de ainda mais crescimento, impacto e realização.','','[]','2026-02-23','alexia','','Concluído','2026-02-20 11:09:09'),(33,26,'Aurélia','Diretoria Pedagógica','Comunicado','Comunicado','Prezados responsáveis,\r\n\r\nComunicamos que hoje, a partir das 13h30, a rede elétrica passará por manutenção, podendo ser restabelecida a qualquer momento.\r\n\r\nOs atendimentos serão mantidos normalmente.\r\n\r\nContamos com a colaboração de todos!','','[]','2026-02-20','Aurélia ','Urgente ','Concluído','2026-02-20 12:46:06'),(34,95,'Alexia Santos','Diretora de RH e Estratégia','Post Instagram','arte de recrutamento e seleção','Utilizar arte abaixo como modelo, alterando para os beneficios ofertados e ID da clinica','','[\"1771860347481-WhatsApp_Image_2026_02_23_at_09.56.41.jpeg\"]','2026-02-25','ALEXIA','','Concluído','2026-02-23 15:25:47'),(35,1,'Marcus TI','Diretoria Geral','Placas','Placa para poder colocar nas recepções sobre o QRCODE de conexão do WIFI de pacientes.','Placa para poder colocar nas recepções sobre o QRCODE de conexão do WIFI de pacientes.','','[]','2026-02-28','Ivanize','Coloca também a senha em baixo. Pacientes@2026','Concluído','2026-02-23 17:20:48'),(36,2,'Maria Júlia Azevedo','Diretoria Geral','Modelo de Slide','Post com foto da equipe ASG ','Parabéns pelo dia do profissional ASG ','','[]','2026-02-23','IVANIZE','','Concluído','2026-02-23 17:33:08'),(37,79,'RH','RH','Outros','convite café da manhã dia da mulher 09/03 a partir de 09h da manhã','Abertos a sugestão ','','[]','2026-02-26','Ester','','Concluído','2026-02-25 14:26:09'),(38,52,'Nathali','Coordenação TCC/AVN','Comunicado','Convite de cerimônia de alta.\r\n','Utilizar o mesmo modelo, somente alterando data e horário.\r\nData: 09/03/2026\r\nHorário: 17:30h','','[]','2026-02-26','Nathali','','Concluído','2026-02-26 11:30:04'),(39,26,'Aurélia','Diretoria Pedagógica','Comunicado','Comunicado','Prezados pais e responsáveis,\r\n\r\nComunicamos que a profissional Pollyana encontra-se de atestado médico. Em razão disso, as devolutivas agendadas para quinta e sexta-feira desta semana serão adiadas para quinta e sexta-feira da próxima semana.\r\n\r\nInformamos que os atendimentos de hoje e amanhã estão mantidos e serão realizados pela equipe de Neuropsicopedagogia.\r\n\r\nAtenciosamente,\r\nDiretoria Pedagógica','','[]','2026-02-26','Aurélia ','Urgência ','Concluído','2026-02-26 13:01:55'),(40,79,'RH','RH','Vídeo','Cronograma de postagem (pódio)','Reforçar sobre o ponto 1 vez por mês','','[]','2026-02-26','Alexia','','Concluído','2026-02-26 13:35:50'),(41,79,'RH','RH','Eventos','workshop ATs','identidade visual do evento, arte de camisetas, garras e etc.. criar um marketing de adesão','','[]','2026-03-30','Ester','','Pendente','2026-02-26 13:36:59'),(42,79,'RH','RH','Outros','Post de promoção no linkedin','Mostrar que o colaborador foi promovido de cargo, seguindo modelos que outras empresas usam no linkedin','','[]','2026-03-02','Alexia','','Em Produção','2026-02-26 13:41:16'),(43,1,'Marcus TI','Diretoria Geral','Placas','ARTE PARA PLACA PARA POR NO BANHEIRO.','LIVRE de uma lado da face da placa e do outro OCUPADO.','https://br.pinterest.com/pin/78742693479660369/','[]','2026-03-02','Ivanize','','Negado','2026-02-26 13:41:37'),(44,79,'RH','RH','Outros','Arte tubolata','Seguindo arte que já estava sendo utilizada anteriormente. apenas adicionar a arte na parte de cima','','[]','2026-02-27','Alexia','','Negado','2026-02-26 13:42:17'),(45,79,'RH','RH','Outros','Arte tubolata ','seguir o mesmo modelo anterior apenas fazer a parte de cima','','[]','2026-02-27','Alexia','','Concluído','2026-02-26 13:50:45'),(46,79,'RH','RH','Outros','Patrocinar vaga de TO no linkedin','Patrocinar vaga de TO no linkedin','','[]','2026-02-27','Alexia','','Concluído','2026-02-27 17:36:41'),(47,79,'RH','RH','Outros','Organizar impressão de carteirinha','Colocar em A4','','[]','2026-03-02','Ester','','Concluído','2026-03-02 12:31:14'),(48,79,'RH','RH','Post Instagram','Divulgar vaga de Atendente terapêuticoo em Palmas','Não precisa colocar horário ou região específico ','','[]','2026-03-04','Ester','','Concluído','2026-03-02 12:57:35'),(49,79,'RH','RH','Outros','Cartão de retorno de férias da colaboradora Joyce, Ana Paula e Aurélia.','Mesmo modelo que já vem sendo utilizado','','[]','2026-03-05','Ester','','Concluído','2026-03-05 11:35:39'),(50,7,'Kare','Faturamento - Unidade 3','Outros','Foto da fachada;\r\nFoto do banheiro com placa de identificação\r\nFoto das salas de atendimento: Psicologia, Psicologia ABA, Terapia Ocupacional, Psicomotricidade, Fisioterapia, Fonoaudiologia, Neuropsicologia, Neuropsicopedagogia, Audiologia.\r\nFoto da recepção. (Neuro II)','Preciso de fotos da clinica devidamente identificada para finalização de credenciamento.\r\nFotos identificadas como Psiconeuro Centro Especializada em Neurodesenvolvimento II LTDA\r\nDevem ser em formato JPEG (até 4MB)','','[\"1772711247655-FOTOS_PARA_CREDENCIAMENTO.png\"]','2026-03-13','KARE','','Concluído','2026-03-05 11:47:27'),(51,79,'RH','RH','Outros','cartaz convênio odontologico','seguir mesmo padrão do clube de benefícios','','[\"1772720076321-Captura_de_tela_2026_03_05_111304.png\"]','2026-03-05','Ester','','Concluído','2026-03-05 14:14:36'),(52,95,'Alexia Santos','Diretora de RH e Estratégia','Placas','placa com ID igual as placas dispostas na copa','COLCHONETES – NORMAS DE USO\r\n\r\nPara garantir a organização e a higiene para todos os colaboradores, siga as orientações abaixo:\r\n\r\n• Utilize o colchonete apenas durante o intervalo de descanso.\r\n• Retire e devolva no mesmo local onde foi encontrado.\r\n• Antes de devolver, higienize o colchonete com o álcool disponível.\r\n• Zele pela conservação do material para que todos possam utilizar.\r\n\r\nContamos com a colaboração de todos para manter o ambiente limpo, organizado e agradável. 🤝','','[]','2026-03-09','ALEXIA','','Concluído','2026-03-09 13:42:26'),(53,79,'RH','RH','Outros','uma plaquinha para colocar no mural onde vamos colocar uma caixa de sugestões','Sua opinião faz a diferença. Deixe aqui sua sugestão!','','[]','2026-03-09','Ester','','Concluído','2026-03-09 14:33:41'),(54,79,'RH','RH','Modelo de Slide','Adicionar clube de descontos atualizado no slide da integração!','Seguer o que foi colocado no mural do RH','','[]','2026-03-11','Ester','','Concluído','2026-03-10 12:10:43'),(55,79,'RH','RH','Modelo de Slide','Adicionar dois slides na lintegração','Slide sobre o pódio da pontualidade e sobre as políticas novas (day off, formação e saúde)','','[]','2026-03-11','Ester','','Concluído','2026-03-10 12:12:09'),(56,79,'RH','RH','Outros','cartão pequeno para colar um batom do lado ','Que este batom lembre vocês do brilho, da força e da beleza que cada uma traz todos os dias para nossa equipe. Obrigada pela dedicação e pelo carinho no trabalho.\r\n\r\nCom carinho\r\nDra Ivanize','','[]','2026-03-11','Ester','','Concluído','2026-03-11 13:36:33'),(57,79,'RH','RH','Eventos','Convite Cerimônia de posse','Mensagem convidando os coordenadores para a ceriMõnia de posse. Data 17/03/2026 Horário 17:00 Local : Sala de reuniões.','','[]','2026-03-12','Alexia ','','Concluído','2026-03-11 19:32:44'),(58,95,'Alexia Santos','Diretora de RH e Estratégia','Outros','Desenvolver um modelo de camiseta que seja uniforme para a equipe de lideres da clinica psiconeuro ','A camiseta precisa conter ID da clinica ','','[]','2026-03-20','ALEXIA','','Concluído','2026-03-16 15:08:24'),(59,79,'RH','RH','Comunicado','Card vacinação','Dia 24/03/20216 ás 08:30h na sala de reuniões','','[]','202