ULL,'2025-12-16 09:26:11',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4844,26,73,'private','Obrigada ',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:26:13',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4848,26,73,'private','Eu preciso saber quais são os protocolos de avaliação utilizados na TCC para responder um questionário da UNIMED',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:26:51',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4849,6,17,'private','Vou te mandar ',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:26:58',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4850,6,17,'private','Kamyla Souza - 63 98459-0898',NULL,'text',NULL,1,0,1,0,NULL,'2025-12-16 09:27:29',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4853,51,21,'private','Obrigada :)',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:30:31',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4854,43,17,'private','Bom dia, obrigada ',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:33:05',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4855,73,26,'private','Certo.\n\nEm Terapia Cognitivo-Comportamental (TCC), a avaliação é um processo contínuo e estruturado que utiliza uma combinação de métodos para identificar e medir o problema do paciente. Os principais \"protocolos\" de avaliação não se referem a um único conjunto de passos rígidos, mas sim a uma variedade de instrumentos e técnicas. \n\n1. Entrevista clínica e anamnese.\n2. Automonitoramento.\n3. Questionários, escalas e inventários padronizados.\n4. Observação clínica.\n5. Técnicas cognitivas e comportamentais como avaliação. \n\nA avaliação na TCC é um processo dinâmico, que se repete ao longo de toda a terapia para monitorar o progresso e ajustar o plano de tratamento conforme necessário. O objetivo é obter uma compreensão abrangente do problema do paciente (a conceitualização cognitiva) para, então, intervir de forma eficaz. ',NULL,'text',NULL,1,0,0,0,4848,'2025-12-16 09:33:23',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4856,73,26,'private','Imagina!',NULL,'text',NULL,1,0,0,0,4844,'2025-12-16 09:33:39',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4857,43,24,'private','pacientes para enviar mensagem informando que finalizou a AVN: Camila Pessoa, Kauan Israel da Silva Raposo, Clemilson Xavier de Oliveira, Flélix Valois Borges de Sousa, Julia Azevedo da Silva e Mathias dos Reis Henrique',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:33:39',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4858,73,17,'private','Obrigada ☺️',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:34:20',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4859,3,29,'private','Nay\n',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:34:52',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4860,72,74,'private','Se for possivel fazer eu faço a solicitação ',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:35:02',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4861,72,74,'private','IMG_3622.jpg',NULL,'file','1765888528674-IMG_3622.jpg',1,0,0,0,NULL,'2025-12-16 09:35:28',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4862,72,74,'private','IMG_3621.jpg',NULL,'file','1765888570179-IMG_3621.jpg',1,0,0,0,NULL,'2025-12-16 09:36:10',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4863,72,74,'private','IMG_3620.jpg',NULL,'file','1765888576975-IMG_3620.jpg',1,0,0,0,NULL,'2025-12-16 09:36:17',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4864,43,24,'private','Thalissom Dutra do Nascimento, Lucas Apolinátrio Abreu, Hellen Emily de Sousa Rocha, João Pedro Galvão Martins e Eliza Fernandes ',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:37:22',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4865,72,74,'private','IMG_3619.jpg',NULL,'file','1765888675527-IMG_3619.jpg',1,0,0,0,NULL,'2025-12-16 09:37:55',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4866,79,2,'private','Bom dia Maria Julia, Neuziane aqui.hoje iniciou uma nova colaboradora para o setor de limpeza, ela se chama Rose, caso consiga um horário hoje para a doutora conhecê-la por gentileza nos informe.\n',NULL,'text',NULL,1,0,0,0,NULL,'2025-12-16 09:40:31',NULL,NULL,NULL,'2026-01-06 14:08:53',0),(4867,73,17,'private','Prof. Armando sol