-01-09 12:55:06',0),(10129,1,63,'private','Sub CorrigirCoresLegenda()\n    Dim ws As Worksheet\n    Dim ultimaLinha As Long\n    \n    \' Desativa atualização de tela para ser mais rápido\n    Application.ScreenUpdating = False\n    \n    \' Loop para passar por TODAS as abas do arquivo\n    For Each ws In ThisWorkbook.Worksheets\n        \n        \' Opção de segurança: Se quiser pular alguma aba específica (ex: \"Menu\"), \n        \' tire a aspa simples da linha abaixo e mude o nome:\n        \' If ws.Name <> \"Menu\" Then\n            \n            \' Copia a formatação da coluna AZ (que está certa)\n            \' Estamos pegando da linha 5 até o fim para não estragar cabeçalhos, \n            \' se seu cabeçalho for maior, mude o A5 para A10, etc.\n            ws.Range(\"AZ5:AZ1000\").Copy\n            \n            \' Cola APENAS A FORMATAÇÃO nas colunas problemáticas (BA até BG)\n            ws.Range(\"BA5:BG1000\").PasteSpecial Paste:=xlPasteFormats\n            \n        \' End If\n    Next ws\n    \n    \' Limpa a memória do copiar/colar\n    Application.CutCopyMode = False\n    Application.ScreenUpdating = True\n    \n    MsgBox \"Pronto! As regras de cores foram aplicadas da coluna BA à BG em todas as abas.\", vbInformation\nEnd Sub',NULL,'text',NULL,1,0,0,0,NULL,'2026-01-09 09:57:26',NULL,NULL,NULL,'2026-01-09 12:57:26',0),(10130,1,63,'private','To indo',NULL,'text',NULL,1,0,0,0,NULL,'2026-01-09 09:57:27',NULL,NULL,NULL,'2026-01-09 12:57:27',0),(10131,3,2,'private','E eu preciso verificar umas coisas com ela também',NULL,'text',NULL,1,0,0,0,NULL,'2026-01-09 09:59:13',NULL,NULL,NULL,'2026-01-09 12:59:13',0),(10132,20,3,'private','Bom dia',NULL,'text',NULL,1,0,0,0,NULL,'2026-01-09 09:59:30',NULL,NULL,NULL,'2026-01-09 12:59:30',0),(10133,3,20,'private','Bom dia',NULL,'text',NULL,1,0,0,0,NULL,'2026-01-09 09:59:38',NULL,NULL,NULL,'2026-01-09 12:59:38',0),(10134,20,3,'private','Cleudson tá aqui para pegar a impressora ',NULL,'text',NULL,1,0,0,0,NULL,'2026-01