INSERT INTO `messages` VALUES (34547,48,50,'private','-Procedimentos Realizados: Utilizamos atividade com Lego, favorecendo organização, planejamento, coordenação motora fina e flexibilidade cognitiva. Durante a proposta, foi estimulada a interação social com outro paciente, promovendo habilidades de comunicação, compartilhamento de materiais e respeito às regras estabelecidas. Estimulação do controle inibitório por meio de jogos com regras. Treino de tempo de espera e alternância de turnos. Atividade estruturada com Lego para planejamento e organização. Mediação de interação social com pares. Reforço positivo para comportamentos adequados e autorregulação.\n-Percepção do Paciente: José apresentou boa participação nas atividades propostas, demonstrando compreensão progressiva das regras e do tempo de espera, necessitando ainda de mediação pontual para manter o controle inibitório. Mostrou-se motivado na construção com Lego e conseguiu interagir com o colega de forma satisfatória, evidenciando avanços nas habilidades sociais. Ao sair queria levar sua construção necessitou de manejo para conduzi-lo a recepção.\n\n*Eucilene Leite*\n*Neuropsicopedagoga*\n*SBNPp 23787*  Em substituição a profissional Pollyana Maione\n\n',NULL,'text',NULL,1,0,0,0,NULL,'2026-02-27 17:03:02',NULL,NULL,NULL,'2026-02-27 20:03:02',0),(34548,1,52,'private','não alteirei',NULL,'text',NULL,1,0,0,0,NULL,'2026-02-27 17:03:03',NULL,NULL,NULL,'2026-02-27 20:03:03',0),(34549,48,50,'private','José Candido 27/02/2026',NULL,'text',NULL,1,0,0,0,NULL,'2026-02-27 17:03:21',NULL,NULL,NULL,'2026-02-27 20:03:21',0),(34551,73,52,'private','🚫 Mensagem apagada',NULL,'file','1772222627780-Altas_m__s_de_Mar__o___Unidade_I_e_II.docx',1,0,1,0,NULL,'2026-02-27 17:03:47',NULL,NULL,NULL,'2026-02-27 20:03:47',0),(34552,48,50,'private','Clecyws- Paciente não compareceu ao atendimento agendado.\n\n\nEucilene Leite\nNeuropsicopedagoga\nSBNPp 23787 Em substituição da Profissional Pollyana Maione',NULL,'text',NULL,1,0,0,0,NUL