NULL,'text',NULL,1,0,0,0,NULL,'2026-04-14 11:31:42',NULL,NULL,NULL,'2026-04-14 14:31:42',0),(58625,45,73,'private','*MIGUEL VICTOR 13/04/2026 15:20 (Isa/Terapia Ocupacional)*\n\n*Procedimentos realizados:\nPaciente realizou atividades de montagem de quebra-cabeça de 60 peças. A proposta teve como objetivo estimular a coordenação motora fina, a coordenação visomotora, a atenção, o raciocínio lógico, permanência em atividade e a organização espacial. \n\n*Comportamentos apresentados:\nPaciente chegou tranquilo, mostrou pouco interesse em realizar a atividade, conseguiu finalizar a atividade durante o atendimento. \n\n*SESSÃO DE SUBSTITUIÇÃO*\n\n*Maria Eduarda da Silva Palmeira\n*Fisioterapeuta/ Psicomotricista- CREFITO 12 398143-F\n',NULL,'text',NULL,1,0,0,0,NULL,'2026-04-14 11:32:00',NULL,NULL,NULL,'2026-04-14 14:32:00',0),(58626,52,9,'private','E da paciente Ana Kamila da Silva também',NULL,'text',NULL,1,0,0,0,NULL,'2026-04-14 11:32:28',NULL,NULL,NULL,'2026-04-14 14:32:28',0),(58627,76,73,'private','Bom dia',NULL,'text',NULL,1,0,0,0,NULL,'2026-04-14 11:32:49',NULL,NULL,NULL,'2026-04-14 14:32:49',0),(58628,76,73,'private','se estiver disposnivel pode vim aqui na sala p/ eu fazer o relatório',NULL,'text',NULL,1,0,0,0,NULL,'2026-04-14 11:34:00',NULL,NULL,NULL,'2026-04-14 14:34:00',0),(58629,52,56,'private','Armando a responsável do paciente Pedro Henrique Matsuda Soares Severino deseja agendar uma devolutiva',NULL,'text',NULL,1,0,0,0,NULL,'2026-04-14 11:35:08',NULL,NULL,NULL,'2026-04-14 14:35:08',0),(58630,56,52,'private','Ok',NULL,'text',NULL,1,0,0,0,NULL,'2026-04-14 11:36:09',NULL,NULL,NULL,'2026-04-14 14:36:09',0),(58631,95,1,'private','Beleza! Se precisar de algo me avise',NULL,'text',NULL,1,0,0,0,NULL,'2026-04-14 11:36:15',NULL,NULL,NULL,'2026-04-14 14:36:15',0),(58632,95,3,'private','Bom diaa',NULL,'text',NULL,1,0,0,0,NULL,'2026-04-14 11:36:25',NULL,NULL,NULL,'2026-04-14 14:36:25',0),(58633,95,3,'private','fazemos como agora?',NULL,'text',NULL,1,0,0,0,NULL,'2026-