INSERT INTO `messages` VALUES (89194,50,73,'private','Pacientes faltosos dos dias 08 a 12/06\n1.	Alice Barbosa Ronzani (Justificou que estava com febre)\n2.	Carlos Alexandre de Souza Martins 2 faltas (a mãe relatou na recepção que está com dificuldade de trazer de manhã devido está muito irritado e sonolento por causa da medicação.)\n3.	Lauanny Pinheiro Gomes 3 faltas (Família justificou que estão de luto)\n4.	Arthur Antônio Martins dos Santos 1 falta (Quando o paciente vem sempre chega atrasado de 15 a 20 minutos.)\n5.	Beatriz Gutierrez Yamamoto Milhomem 1 falta\n6.	Felipe Melo Dias 1 falta\n',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-15 09:17:52',NULL,NULL,NULL,'2026-06-15 12:17:52',0),(89195,72,112,'private','Talvez tenha sido o faturamento, porque eles confundem mesmo ',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-15 09:18:00',NULL,NULL,NULL,'2026-06-15 12:18:00',0),(89196,122,73,'private','Larissa, me enganei era da Helena Alves. Encontrei aqui o Laudo.',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-15 09:18:02',NULL,NULL,NULL,'2026-06-15 12:18:02',0),(89197,112,72,'private','Aqui no wpp não tem nenhum registro de conversa com ela! ','Ester','text',NULL,1,0,0,0,89195,'2026-06-15 09:18:20',NULL,NULL,NULL,'2026-06-15 12:18:20',0),(89198,65,72,'private','Mensagem para a AT Ana Luiza do paciente (Davi Oliveira)\n\nOlá Ana, bom dia! \nAqui supervisor Gabriel, entrando em contato para confirmar nossa supervisão online hoje as 14:00.\nSegue o link do meet:  https://meet.google.com/wto-bibg-eip',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-15 09:18:26',NULL,NULL,NULL,'2026-06-15 12:18:26',0),(89199,79,33,'private','Bom dia, qual tamanho do seu uniforme?','Celismar','text',NULL,1,0,0,0,NULL,'2026-06-15 09:18:44',NULL,NULL,NULL,'2026-06-15 12:18:44',0),(89200,112,72,'private','E o setor de agendamento normalmente não passa essas informações sobre guias que finalizaram..','Ester','text',NULL,1,0,0,0,NULL,'2026-06-15 09:18:54',NULL,NULL,NULL,'2026-06-15 12:18:54',0),(89201,72,65,'private','feit