manecemos à disposição para um possível retorno futuramente, conforme disponibilidade de agenda. Caso haja interesse, pedimos que entrem em contato para que possamos orientar sobre os próximos passos.\nAgradecemos a compreensão.\n\nAtenciosamente,\nNathali Gonçalves dos Passos\nCoordenadora de Terapias -TCC e AVN - Clínica Psiconeuro',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-24 08:40:55',NULL,NULL,NULL,'2026-06-24 11:40:55',0),(95302,26,112,'private','Para Ester ☝🏻',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-24 08:41:34',NULL,NULL,NULL,'2026-06-24 11:41:34',0),(95303,129,73,'private','Enviei pra vocês, para o agendamento e para Marismar.',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-24 08:41:48',NULL,NULL,NULL,'2026-06-24 11:41:48',0),(95304,98,79,'private','Bom dia! De segunda a quinta até as 17 horas e sexta até 16 horas ',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-24 08:43:40',NULL,NULL,NULL,'2026-06-24 11:43:40',0),(95305,79,55,'private','não, ja encontrei aqui, obrigada','Celismar','text',NULL,1,0,0,0,NULL,'2026-06-24 08:44:54',NULL,NULL,NULL,'2026-06-24 11:44:54',0),(95306,129,26,'private','Oie, não recebi o documento.',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-24 08:45:39',NULL,NULL,NULL,'2026-06-24 11:45:39',0),(95307,55,73,'private','ele veio ontem ',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-24 08:45:47',NULL,NULL,NULL,'2026-06-24 11:45:47',0),(95308,55,79,'private','pornada ',NULL,'text',NULL,1,0,0,0,NULL,'2026-06-24 08:45:53',NULL,NULL,NULL,'2026-06-24 11:45:53',0),(95309,112,26,'private','Obrigada! ','Ester','text',NULL,1,0,0,0,NULL,'2026-06-24 08:46:30',NULL,NULL,NULL,'2026-06-24 11:46:30',0),(95310,39,93,'private','RELATORIO AC JUNHO - SAMUEL.docx',NULL,'file','1782301540044-RELATORIO_AC_JUNHO___SAMUEL.docx',1,0,0,0,NULL,'2026-06-24 08:47:51',NULL,NULL,NULL,'2026-06-24 11:47:51',0),(95311,79,98,'private','Obrigadaa','ALEXIA','text',NULL,1,0,0,0,NULL,'2026-06-24 08:47:52',NULL,NULL,NULL,'2026-06-24 11:47:52',0),(95312,79,98,'private','ainda essa semana chamo voce apra ajusta