INSERT INTO `rh_arquivos` VALUES (3,'Boas vindas! 💙 ','informativo','/uploads/1773153875310-equiperh.png',' Olá Equipe!\r\n\r\nInformamos que o Portal do RH já está disponível. A nova ferramenta foi implementada para facilitar o acesso às informações e serviços de Recursos Humanos, trazendo mais agilidade, organização e transparência nos processos internos.\r\n\r\nPor meio do portal, será possível acompanhar e solicitar diversos serviços de forma simples e rápida, como:\r\n- Acesso a informações funcionais;\r\n- Solicitações e acompanhamentos junto ao RH;\r\n- Comunicados institucionais;\r\n- Documentos e orientações importantes.\r\n\r\nEssa iniciativa reforça nosso compromisso em modernizar processos e melhorar a experiência dos colaboradores. Em caso de dúvidas sobre o acesso ou utilização do portal, entre em contato com o RH.\r\n\r\nAlexia, Ester, Neuziane e Idalina. 💙 \r\nEquipe de RH Psiconeuro \r\nAtender, satisfazer e encantar. ✨','2026-03-10 14:44:35'),(5,'✨ Mais uma conquista que nos enche de orgulho!','informativo','/uploads/1776364596281-1776337629874-comunicado_publico.png','✨ Mais uma conquista que nos enche de orgulho!\r\n\r\nÉ com grande satisfação que comunicamos a promoção da Marismar para o cargo de Coordenadora de Faturamento. Sua trajetória é marcada por uma forte competência técnica, aliada à doçura no trato com as pessoas e uma admirável capacidade de repassar conhecimento — qualidades que fazem dela uma profissional completa e referência para a equipe.\r\n\r\nAo longo dessa jornada, Marismar demonstrou não apenas domínio dos processos, mas também o compromisso em desenvolver pessoas, contribuir com melhorias e fortalecer os resultados do setor.\r\n\r\nTemos plena confiança de que, nesta nova etapa, seguirá conduzindo o time com excelência, organização e sensibilidade, potencializando ainda mais o crescimento e a qualidade do nosso faturamento.\r\n\r\nParabéns por essa conquista! 💙🚀\r\nSeguimos juntos, atendendo, satisfazendo e encantando todos os dias.','2026-04-16 18:36:36'),(6,'✨ Temos uma grande conquista para celebrar!','informativo','/uploads/1776364628271-1776165168734-comunicado_publico.png','✨ Temos uma grande conquista para celebrar!\r\n\r\nÉ com muito orgulho que anunciamos a promoção da Sâmia para o cargo de Líder de Recepção. Ao longo de seus 3 anos de casa, ela construiu uma trajetória marcada por dedicação, responsabilidade, lealdade e um verdadeiro espírito Psiconeuro — valores que refletem diretamente em sua evolução e nos resultados que entrega.\r\n\r\nTemos certeza de que, nesta nova etapa, ela continuará fazendo a diferença, fortalecendo o atendimento, a organização da equipe e proporcionando uma experiência cada vez mais acolhedora e eficiente para todos.\r\n\r\nParabéns por essa conquista! 💙🚀\r\nSeguimos juntos, atendendo, satisfazendo e encantando todos os dias.','2026-04-16 18:37:08'),(7,'ADESÃO IFOOD BENEFÍCIOS','informativo','/uploads/1777410866823-WhatsApp Video 2026-04-28 at 17.47.00.mp4','✨ O suspense acabou! ✨\r\n\r\nTem novidade chegando para facilitar o dia a dia de todo mundo: mudamos para o iFood Benefícios! 🍽️💳\r\n\r\nSe você ainda não está cadastrado(a), procure o seu gestor ou o RH para realizar o cadastro o quanto antes, combinado? Assim você já consegue aproveitar tudo sem atraso 😊\r\n\r\nQualquer dúvida, estamos por aqui! 💙\r\n','2026-04-28 21:14:27'),(9,'Política de Antecedentes Criminais','informativo','/uploads/1780054348806-PolÃ­tica Interna de Antecedentes Criminais.pdf','Prezados(as),\r\n\r\nCom o objetivo de mantermos um ambiente cada vez mais seguro, acolhedor e protegido para colaboradores, pacientes e famílias, solicitamos, por gentileza, o envio da certidão de antecedentes criminais atualizada, documento necessário para atuação em nossa instituição.\r\n\r\nEssa solicitação reforça nosso compromisso com o cuidado, a ética e o bem-estar das crianças neurodivergentes atendidas em nossa clínica.\r\n\r\nA certidão pode ser emitida gratuitamente e a qualquer momento pelo portal gov.com.br, em: “Baixar Certidões” → “Certidão de Antecedentes Criminais”.\r\n\r\nCaso tenham qualquer dificuldade durante o processo, o setor de RH está à disposição para auxiliar no que for necessário.\r\n\r\nPedimos, por gentileza, que o envio seja realizado até o dia 19/06/2026.\r\n\r\nContamos com a compreensão e colaboração de todos 💙','2026-05-29 11:32:29'),(10,'☕💬 *Roda de Conversa Ser & Cuidar – 2º Encontro Café, Caos & Colaboração*','informativo','/uploads/1780080197117-convite roda de conversa.png','☕💬 *Roda de Conversa Ser & Cuidar – 2º Encontro Café, Caos & Colaboração*\r\n\r\nPreparamos um momento especial de troca, escuta e conexão entre equipes, conduzido e mediado por Isadora Brasil. ✨\r\n\r\nSerá um espaço leve e acolhedor para conversarmos sobre vivências, desafios do dia a dia e fortalecimento das relações no ambiente de trabalho.\r\n\r\nPara organização do encontro, pedimos que confirmem sua participação através do link abaixo:\r\n🔗 https://forms.gle/eCsUu7YLJQzSvVoHA\r\n\r\nContamos com a presença de vocês para mais esse momento de conexão e colaboração! 💛\r\n','2026-05-29 18:43:17'),(11,'🏆✨ O ranking saiuuu! ✨🏆','informativo','/uploads/1780084820196-PÃ³dio da Pontualidade (1).png','\r\n\r\nOs TOP 10 da pontualidade já estão brilhando no mural do Neurogente 💙⏰\r\n\r\nCompromisso, organização e dedicação que merecem reconhecimento! 👏\r\nAgora é oficial: pontualidade também dá pódio 😎🔥\r\n\r\nCorre lá no mural conferir quem garantiu lugar entre os destaques do mês 👀','2026-05-29 20:00:20'),(12,'Temos a alegria de compartilhar mais uma conquista que fortalece a nossa equipe! 💙','informativo','/uploads/1781094529228-comunicadoluiza.jpeg','É com grande orgulho que oficializamos a promoção de Luiza Idriss para o cargo de Terapeuta Ocupacional Responsável Técnica na Terapia Ocupacional, que iniciou em 01/05/2026.\r\n\r\nEssa conquista é resultado de uma trajetória marcada por dedicação, responsabilidade, evolução constante e entregas que impactam diretamente nossos pacientes, famílias e equipe.\r\n\r\nNesta nova etapa, Luiza assume a missão de garantir a qualidade técnica, ética e assistencial dos serviços de Terapia Ocupacional da Clínica Psiconeuro, contribuindo para o desenvolvimento da equipe e para a excelência dos nossos atendimentos.\r\n\r\nParabenizamos Luiza por essa importante conquista e desejamos muito sucesso nessa nova jornada! 🚀✨\r\n\r\nSeguimos firmes em nosso propósito de Atender, Satisfazer e Encantar 💙','2026-06-10 12:28:49'),(13,'💙 Uma trajetória construída com dedicação, evolução e propósito!','informativo','/uploads/1781179851644-Comunicado publicO de promoção  (5).png','\r\n\r\nAo longo de 3 anos conosco, Ester Mello vem demonstrando comprometimento, agilidade e uma comunicação que faz a diferença no dia a dia. Com olhar atento, postura resolutiva e muita sagacidade, conquistou seu espaço através de atitudes que refletem nosso jeito de cuidar das pessoas.\r\n\r\nSua nova jornada como Coordenadora de Atendimento ao Cliente representa o reconhecimento de uma profissional que entende que cada detalhe importa e que cada atendimento é uma oportunidade de atender, satisfazer e encantar.\r\n\r\nQue essa nova etapa seja marcada por ainda mais conquistas, liderança e impacto positivo na nossa equipe e nos nossos clientes. 🚀✨\r\n\r\nParabéns, Ester! Temos muito orgulho da sua caminhada. 💙','2026-06-11 12:10:51');
/*!40000 ALTER TABLE `rh_arquivos` ENABLE KEYS */;
UNLOCK TABLES;

